#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_POOL_SIZE 16
#define AUTH_TOKEN_LEN 64
#define CONN_TIMEOUT_MS 5000

typedef struct auth_ctx auth_ctx_t;
typedef void (*auth_callback_t)(auth_ctx_t *ctx, int status, const char *token);

typedef struct {
    int fd;
    bool in_use;
    pthread_mutex_t lock;
    unsigned int ref_count;
    auth_ctx_t *pending_ctx;
} conn_slot_t;

struct auth_ctx {
    char username[128];
    char nonce[32];
    auth_callback_t on_complete;
    void *user_data;
    conn_slot_t *assigned_slot;
    int retry_count;
    bool cancelled;
};

typedef struct {
    conn_slot_t slots[MAX_POOL_SIZE];
    pthread_mutex_t pool_lock;
    int active_count;
} conn_pool_t;

static conn_pool_t g_pool;

void pool_init(void) {
    memset(&g_pool, 0, sizeof(g_pool));
    pthread_mutex_init(&g_pool.pool_lock, NULL);
    for (int i = 0; i < MAX_POOL_SIZE; i++) {
        pthread_mutex_init(&g_pool.slots[i].lock, NULL);
        g_pool.slots[i].ref_count = 0;
    }
}

static conn_slot_t *pool_acquire(void) {
    pthread_mutex_lock(&g_pool.pool_lock);
    for (int i = 0; i < MAX_POOL_SIZE; i++) {
        if (!g_pool.slots[i].in_use) {
            g_pool.slots[i].in_use = true;
            g_pool.slots[i].ref_count = 1;
            g_pool.active_count++;
            pthread_mutex_unlock(&g_pool.pool_lock);
            return &g_pool.slots[i];
        }
    }
    pthread_mutex_unlock(&g_pool.pool_lock);
    return NULL;
}

static void pool_release(conn_slot_t *slot) {
    pthread_mutex_lock(&slot->lock);
    if (slot->ref_count > 0) {
        slot->ref_count--;
    }
    if (slot->ref_count == 0) {
        slot->in_use = false;
        slot->pending_ctx = NULL;
        pthread_mutex_lock(&g_pool.pool_lock);
        g_pool.active_count--;
        pthread_mutex_unlock(&g_pool.pool_lock);
    }
    pthread_mutex_unlock(&slot->lock);
}

static void slot_add_ref(conn_slot_t *slot) {
    pthread_mutex_lock(&slot->lock);
    slot->ref_count++;
    pthread_mutex_unlock(&slot->lock);
}

/* Simulates async network response arriving on I/O thread */
static void *io_thread_handler(void *arg) {
    conn_slot_t *slot = (conn_slot_t *)arg;

    /* Simulate network latency */
    struct timespec ts = {0, 100000000}; /* 100ms */
    nanosleep(&ts, NULL);

    pthread_mutex_lock(&slot->lock);
    auth_ctx_t *ctx = slot->pending_ctx;
    pthread_mutex_unlock(&slot->lock);

    /* The ctx pointer was captured from the slot.
     * We invoke the callback using the captured context. */
    if (ctx && !ctx->cancelled) {
        char token[AUTH_TOKEN_LEN];
        snprintf(token, AUTH_TOKEN_LEN, "tok_%s_%s", ctx->username, ctx->nonce);
        ctx->on_complete(ctx, 0, token);
    }

    pool_release(slot);
    return NULL;
}

auth_ctx_t *auth_begin(const char *username, auth_callback_t cb, void *user_data) {
    auth_ctx_t *ctx = (auth_ctx_t *)malloc(sizeof(auth_ctx_t));
    if (!ctx) return NULL;

    memset(ctx, 0, sizeof(auth_ctx_t));
    strncpy(ctx->username, username, sizeof(ctx->username) - 1);
    snprintf(ctx->nonce, sizeof(ctx->nonce), "%08x", (unsigned)rand());
    ctx->on_complete = cb;
    ctx->user_data = user_data;
    ctx->cancelled = false;

    conn_slot_t *slot = pool_acquire();
    if (!slot) {
        free(ctx);
        return NULL;
    }

    ctx->assigned_slot = slot;

    pthread_mutex_lock(&slot->lock);
    slot->pending_ctx = ctx;
    pthread_mutex_unlock(&slot->lock);

    /* Add ref for the I/O thread */
    slot_add_ref(slot);

    pthread_t tid;
    pthread_create(&tid, NULL, io_thread_handler, slot);
    pthread_detach(tid);

    return ctx;
}

void auth_cancel(auth_ctx_t *ctx) {
    if (!ctx) return;

    /* Mark as cancelled and release our reference to the slot */
    ctx->cancelled = true;

    conn_slot_t *slot = ctx->assigned_slot;
    if (slot) {
        pool_release(slot);
        ctx->assigned_slot = NULL;
    }

    /* Free the context immediately - caller is done with it */
    free(ctx);
}

/* Example usage showing the vulnerability trigger */
typedef struct {
    bool completed;
    char result_token[AUTH_TOKEN_LEN];
} auth_result_t;

static void on_auth_done(auth_ctx_t *ctx, int status, const char *token) {
    auth_result_t *result = (auth_result_t *)ctx->user_data;
    if (status == 0 && token) {
        strncpy(result->result_token, token, AUTH_TOKEN_LEN - 1);
    }
    result->completed = true;
}

int authenticate_user(const char *username) {
    auth_result_t result = {0};

    auth_ctx_t *ctx = auth_begin(username, on_auth_done, &result);
    if (!ctx) return -1;

    /* Simulate timeout - if auth takes too long, cancel */
    struct timespec ts = {0, 50000000}; /* 50ms timeout */
    nanosleep(&ts, NULL);

    if (!result.completed) {
        /* Timeout: cancel the operation */
        auth_cancel(ctx);
        return -2;
    }

    free(ctx);
    return 0;
}
